// Module 1: Common Anode Seven-Segment Decoder (4-bit BCD to 7-segment) // Common Anode logic: 0 = Segment ON, 1 = Segment OFF // Output mapping: {a, b, c, d, e, f, g} module seg7_decoder ( input logic [3:0] bcd, output logic [6:0] seg ); always_comb begin case (bcd) 4’h0: seg = 7’b0000001; // 0 4’h1: seg = 7’b1001111; // 1 4’h2: seg = 7’b0010010; // 2 4’h3: seg = 7’b0000110; // 3 4’h4: seg = 7’b1001100; // 4 4’h5: seg = 7’b0100100; // 5 4’h6: seg = 7’b0100000; // 6 4’h7: seg = 7’b0001111; // 7 4’h8: seg = 7’b0000000; // 8 4’h9: seg = 7’b0000100; // 9 4’hA: seg = 7’b0001000; // A 4’hB: seg = 7’b1100000; // b 4’hC: seg = 7 me0110001; // C 4’hD: seg = 7’b1000010; // d 4’hE: seg = 7’b0110000; // E 4’hF: seg = 7’b0111000; // F default: seg = 7’b1111111; // Off endcase end endmodule
// Module 2: Time-Multiplexed Dual Seven-Segment Display Controller module seg7_mux_top ( input logic clk, // System clock input logic rst, // Active-high reset input logic [3:0] in0, // First 4-bit BCD input input logic [3:0] in1, // Second 4-bit BCD input output logic [6:0] seg_out, // Cathode segment drive outputs (shared) output logic [1:0] anodes // Common Anodes control (active-low) );
// Clock Divider / Multiplexing Toggle Flag
// For hardware implementation, set counter size to refresh around ~1 kHz to prevent flicker
logic [15:0] refresh_counter;
logic        select_reg;

always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
        refresh_counter &lt;= '0;
        select_reg      &lt;= 1'b0;
    end else begin
        refresh_counter &lt;= refresh_counter + 1'b1;
        select_reg      &lt;= refresh_counter[15]; // Toggles active display
    end
end

// 2-to-1 Multiplexer for BCD inputs
logic [3:0] current_bcd;
assign current_bcd = select_reg ? in1 : in0;

// Single Decoder Instance
seg7_decoder u_decoder (
    .bcd (current_bcd),
    .seg (seg_out)
);

// Active-Low Anode Controller (Enable one display at a time)
// anodes[0] drives Display 0, anodes[1] drives Display 1
assign anodes = select_reg ? 2'b10 : 2'b01;
endmodule
// Module 3: Testbench module seg7_mux_tb;
logic       clk;
logic       rst;
logic [3:0] in0;
logic [3:0] in1;
logic [6:0] seg_out;
logic [1:0] anodes;

// Instantiate Unit Under Test (UUT)
seg7_mux_top uut (
    .clk     (clk),
    .rst     (rst),
    .in0     (in0),
    .in1     (in1),
    .seg_out (seg_out),
    .anodes  (anodes)
);

// Clock generation (100MHz)
always #5 clk = ~clk;

initial begin
    clk = 0;
    rst = 1;
    in0 = 4'h3; // Display 0 should show '3'
    in1 = 4'hA; // Display 1 should show 'A'

    #20 rst = 0;

    // Monitor multiplexing transitions
    #100000;
    $display("Input 0: %h, Input 1: %h", in0, in1);
    $finish;
end
endmodule









NotePrompt with File Attachment





module top_mux_7seg ( input logic clk, input logic reset, input logic en, input logic [3:0] in0, input logic [3:0] in1, output logic [6:0] seg0, output logic [6:0] seg1 );
logic mux_sel;
logic [3:0] current_in;
logic [6:0] decoded_seg;

// Instantiate provided clock divider/oscillator module
blinker #(
    .WIDTH(23),
    .MAX(23'd10000) // Lowered max count to toggle faster for time multiplexing
) osc_inst (
    .int_osc(clk),
    .reset(reset),
    .en(en),
    .fpga_blink_out(mux_sel)
);

// Mux 1: Select between the two 4-bit inputs based on clock state
assign current_in = mux_sel ? in1 : in0;

// Instantiate provided 7-segment decoder
decoder decoder_inst (
    .s(current_in),
    .seg(decoded_seg)
);

// Demux / Register output: Hold and display the decoded bits for each segment
always_ff @(posedge clk or negedge reset) begin
    if (!reset) begin
        seg0 &lt;= 7'b1111111; // Off state for common anode
        seg1 &lt;= 7'b1111111;
    end else begin
        if (mux_sel) begin
            seg1 &lt;= decoded_seg;
        end else begin
            seg0 &lt;= decoded_seg;
        end
    end
end
endmodule



For clarity, the two prompts were as follows:
Write SystemVerilog HDL to time multiplex a single seven segment decoder (that decodes from four bits to a common anode seven segment display) to decode two sets of input bits and drive two sets of seven output bits.
Write SystemVerilog HDL to time multiplex a single seven segment decoder (that decodes from four bits to a common anode seven segment display) to decode two sets of input bits and drive two sets of seven output bits. Use the seven segment decoder and oscillator provided in the attached files.
I decided to prompt Gemini via the Harvey Mudd license (as to not train the AI) and I was presented with the first block of code in this section. Notably, it is quite dense and has some distinct deviations from my approach including unclear signal names, lack of parameterization (which wasn’t specified but is definitely valuable for testbenches), and only a singular VERY SHORT testbench that doesn’t thoroughly check things. It didn’t synthesize the first time because of some strange misspelling in the always_comb statement and I did try pasting all of this in a singular .sv file (with successful synthesization) though I suspect different files would be preferred.
When prompting Gemini in a new tab with attached files it did remarkably well in calling my files and organizing the signals which genuinely surprised me since I thought it’d be unresponsive to the files or make things up. This time around, a de-mux block of code of used which seems to essentially be the sActive mux logic with some strange reset cases.
Figure 5 shows a screenshot of the synthesis and warnings that appeared. Some are minor but the “clk” blurb made me realize it didn’t leverage the internal oscillator which my counter module depends on. It also preferred using clk as a signal name over my consistent int_osc. Overall, AI seems to be even stronger with a basis in files but it lacks some of the creative decisions I made while making logic.
